import type { ErrorComponentProps } from "@tanstack/react-router";

import { ErrorDetails } from "./panics";

/**
 * A production page hides error text; the server reports its route failure to the console.
 */
export function TinkerError({
  error,
  dev,
  server,
}: ErrorComponentProps & { dev: boolean; server: boolean }) {
  if (server) console.error("tinker: a route failed on the server:", error);
  return <ErrorDetails error={error} dev={dev} />;
}

/** The base's 404 page; a route's own notFoundComponent, or the router command, replaces it. */
export function TinkerNotFound() {
  return (
    <main>
      <h1>Not found</h1>
    </main>
  );
}

import { tag } from "@tinker/core";
import type { Observe } from "@tinker/core";

/** The command binds render observation; each request borrows it from its own app root. */
export const renderObservation = tag<Observe.Config | undefined>({
  label: "start.renderObservation",
  default: undefined,
});

import { inspect } from "node:util";

/** Report unhandled work, close through the caller, then leave with failure. */
export function observeServerPanics(
  abort: (error: unknown) => void,
  closed: Promise<unknown>,
  stderr: { write(chunk: string): unknown },
): () => void {
  const fail = async (error: unknown) => {
    try {
      abort(error);
      await closed;
    } catch (cleanup) {
      stderr.write(`server close failed: ${inspect(cleanup)}\n`);
    }
  };
  process.on("unhandledRejection", fail);
  return process.off.bind(process, "unhandledRejection", fail);
}

/**
 * Dev only. Start answers a failed render with a bare JSON 500, and that page has no Vite
 * client, so it never sees the fix. This page keeps the body and reloads on the next update.
 * @param request - From the server entry; why: only a browser page load gets the HTML page.
 * @param response - From Start; why: every other response passes through untouched.
 */
export async function devErrorPage(request: Request, response: Response): Promise<Response> {
  const page = request.headers.get("accept")?.includes("text/html");
  const json = response.headers.get("content-type")?.includes("application/json");
  if (response.status !== 500 || !page || !json) return response;
  const body = (await response.text()).replaceAll("&", "&amp;").replaceAll("<", "&lt;");
  return new Response(
    `<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <title>Error</title>
    <script type="module">
      import { createHotContext } from "/@vite/client";
      createHotContext("/@tinker/dev-error").on("vite:beforeUpdate", () => location.reload());
    </script>
  </head>
  <body>
    <pre>${body}</pre>
    <p>tinker: the page failed to render; the error is in the terminal.</p>
    <p>Save a fix and this page reloads.</p>
  </body>
</html>`,
    { status: 500, headers: { "content-type": "text/html; charset=utf-8" } },
  );
}

/** Show the error text only when the entry is in dev mode. */
export function ErrorDetails({ error, dev }: { error: unknown; dev: boolean }) {
  const detail = dev ? (error instanceof Error ? error.message : String(error)) : undefined;

  return (
    <main>
      <h1>Something went wrong</h1>
      {detail !== undefined && <pre>{detail}</pre>}
    </main>
  );
}

import { createRouter } from "@tanstack/react-router";
import type { RouterConstructorOptions, RouterHistory } from "@tanstack/react-router";
import { getGlobalStartContext } from "@tanstack/react-start";
import { extension, resource, tag } from "@tinker/core";
import { ScopeProvider } from "@tinker/react";
import type { ReactNode } from "react";

import { TinkerError, TinkerNotFound } from "./fallbacks";
import { renderObservation } from "./observe";

export type RouteTree = (typeof import("#tinker/routes"))["routeTree"];
type Options = RouterConstructorOptions<RouteTree, "never", false, RouterHistory, object>;
export type RouterOptions = Partial<Omit<Options, "routeTree" | "Wrap" | "context">>;
export type RouterHooks = Pick<Options, "context" | "dehydrate" | "hydrate">;

/** Each server render borrows its request's observer; the command owns browser observation. */
export function readRenderObservation() {
  return getGlobalStartContext()?.scope?.resolve(renderObservation);
}

/** React borrows the current app root through its native provider contract. */
export const routerScope = extension({
  label: "router.scope",
  hooks: {
    async start({ next, scope }) {
      await next();
      return function Wrap({ children }: { children?: ReactNode }) {
        return <ScopeProvider scope={scope}>{children}</ScopeProvider>;
      };
    },
  },
});

export const pageEvents = tag<EventTarget | undefined>({
  label: "router.pageEvents",
  default: undefined,
});

/** A real page hide closes the command's roots; a cached page keeps them. */
export const tabLifetime = resource({
  label: "router.tabLifetime",
  depends: { target: pageEvents },
  factory: ({ target }, { defer }) => {
    let close: (() => Promise<void>) | undefined;
    const leave = (event: Event) => {
      if (!("persisted" in event) || !event.persisted) return close?.();
    };
    target?.addEventListener("pagehide", leave);
    defer(() => target?.removeEventListener("pagehide", leave));
    return {
      bind(next: () => Promise<void>) {
        close = next;
      },
    };
  },
});

/** Load Start's route tree lazily and attach its fallback views and provider. */
export async function createRouterEntry({
  options,
  Wrap,
  close,
  dev,
  server,
}: {
  options: RouterOptions & RouterHooks;
  Wrap: Options["Wrap"];
  close: () => Promise<void>;
  dev: boolean;
  server: boolean;
}) {
  // The module loader caches the route tree; Vite swaps it in dev after a route edit.
  const { routeTree } = await import("#tinker/routes");
  return Object.assign(
    createRouter({
      scrollRestoration: true,
      defaultErrorComponent: (props) => <TinkerError {...props} dev={dev} server={server} />,
      defaultNotFoundComponent: TinkerNotFound,
      ...options,
      routeTree,
      Wrap,
    }),
    { close },
  );
}

declare module "@tanstack/react-router" {
  interface Register {
    router: Awaited<ReturnType<typeof createRouterEntry>>;
  }
}

import {
  createStartHandler as createStart,
  defaultStreamHandler as renderStream,
} from "@tanstack/react-start/server";
import type { Scope } from "@tinker/core";

import { raise } from "~/components/errors";
import { renderFrames } from "~/components/requests/index.server";

import { devErrorPage } from "./panics";
import type { createRouterEntry } from "./router-entry";

/** The command retains both roots; Start borrows context and observation. */
export declare namespace ServerEntry {
  type Next = (request: Request) => Promise<Response>;
  type Handle = {
    requestContext: { scope: Scope.Handle };
    fetch?(request: Request, next: Next): Promise<Response> | Response;
  };
}

/** Render over the supplied app; request bodies retain each render's close. */
export function createServerHandler(app: ServerEntry.Handle, { dev }: { dev: boolean }) {
  const renderRequest = createStart(async (context) => {
    const router: typeof context.router & {
      close?: Awaited<ReturnType<typeof createRouterEntry>>["close"];
    } = context.router;
    if (typeof router.close !== "function") raise("StartScopeMissing", {});
    app.requestContext.scope.resolve(renderFrames).retain(context.request, router.close);

    try {
      return await renderStream(context);
    } catch (error) {
      await router.close();
      throw error;
    }
  });

  return {
    fetch(this: void, request: Request) {
      const next = async (forwarded: Request) => {
        const response = await renderRequest(forwarded, { context: app.requestContext });
        return dev ? devErrorPage(forwarded, response) : response;
      };
      return app.fetch ? app.fetch(request, next) : next(request);
    },
  };
}

/** A stopped command still satisfies the host's server result check. */
export async function stoppedFetch() {
  return new Response(null, { status: 503 });
}

import { createCsrfMiddleware, createStart } from "@tanstack/react-start";

/** Start owns one CSRF guard and caches the command's async options once. */
export function createStartEntry(
  read: (
    csrf: ReturnType<typeof createCsrfMiddleware>,
  ) => ReturnType<Parameters<typeof createStart>[0]>,
) {
  const csrf = createCsrfMiddleware({ filter: (ctx) => ctx.handlerType === "serverFn" });
  let options: ReturnType<typeof read> | undefined;
  return createStart(() => (options ??= read(csrf)));
}

import { writeSync } from "node:fs";
import { setTimeout as sleep } from "node:timers/promises";
import { parentPort, workerData } from "node:worker_threads";

export declare namespace TelemetryWorker {
  type Health = { kind: string; pending: number; dropped: number };
  /** What the request side resolved and sent in `workerData`. */
  type Settings = {
    service: string;
    traces: string;
    logs: string;
    fd: number | null;
    relay: boolean;
  };
  /** The console mirror's sink: the descriptor, or posts back when the host's sink has none. */
  type Output = { writableNeedDrain: boolean; write(text: string): void };
  /** What the command binds inline: the request side's settings and the descriptor sink. */
  type Input = { settings: Settings; console: Output | null };
  /** The worker root's drain, as this glue drives it. */
  type Drain = {
    take(line: string): void;
    health(): Health;
    report(): Health | undefined;
    watch(listener: () => void): void;
    flush(): Promise<void>;
    close(): Promise<Health>;
  };
}

type Shared = { data: Uint8Array; state: Int32Array; settings: TelemetryWorker.Settings };

/** The worker's inputs, as the request side sent them; the command binds them inline. */
export function telemetryWorkerInput(): TelemetryWorker.Input {
  const { settings } = workerData as Shared;
  if (settings.fd === null) {
    if (!settings.relay) return { settings, console: null };
    // A host sink with no descriptor writes on the request thread, as the in-process path did.
    const port = parentPort!;
    return {
      settings,
      console: { writableNeedDrain: false, write: (text) => port.postMessage({ console: text }) },
    };
  }

  const fd = settings.fd;
  const held: Buffer[] = [];
  const console = {
    writableNeedDrain: false,
    /** Lines go straight to the descriptor, as sonic-boom does; EAGAIN waits a turn. */
    write(text: string) {
      if (text) held.push(Buffer.from(text));

      while (held.length) {
        const next = held[0]!;
        let written: number;
        try {
          written = writeSync(fd, next);
        } catch (error) {
          if ((error as { code?: string }).code !== "EAGAIN") throw error;
          console.writableNeedDrain = true;
          setTimeout(() => console.write(""), 1);
          return;
        }
        if (written < next.length) held[0] = next.subarray(written);
        else held.shift();
      }

      console.writableNeedDrain = false;
    },
  };
  return { settings, console };
}

/**
 * Native glue for the telemetry worker: ring reads, the port, and close.
 * @param drain - From the command's worker root; why: the queue that sends and mirrors.
 */
export async function serveTelemetryWorker(drain: TelemetryWorker.Drain) {
  const { data, state } = workerData as Shared;
  const port = parentPort!;
  const bytes = Buffer.from(data.buffer, data.byteOffset, data.byteLength);
  const control = { closing: false, flushes: [] as number[] };
  let read = Atomics.load(state, 1);

  /** Health crosses threads only when its kind changes; every returned send changes it. */
  const post = () => {
    const health = drain.report();
    if (health) port.postMessage({ health });
  };
  drain.watch(post);

  port.on("message", (message: { close?: true; flush?: number }) => {
    if (message.close) control.closing = true;
    if (message.flush !== undefined) control.flushes.push(message.flush);
    Atomics.notify(state, 0);
  });

  port.postMessage({ ready: true });

  for (;;) {
    const at = Atomics.load(state, 0);
    if (at !== read) {
      const lines = ringLines(bytes, read, at);
      read = at;
      Atomics.store(state, 1, read);
      await takeLines(drain, lines, control);
      continue;
    }

    while (control.flushes.length) {
      await drain.flush();
      port.postMessage({ flushed: control.flushes.shift()! });
    }
    if (control.closing) break;

    // Poll every 10 ms; the request side wakes the worker early once a quarter of the ring waits.
    const wait = Atomics.waitAsync(state, 0, at, 10);
    if (wait.async) await wait.value;
  }

  port.postMessage({ final: await drain.close() });
  port.close();
}

/**
 * The whole lines between two ring indexes; the request side writes only whole lines.
 * @param bytes - From the shared ring; why: the text the request thread wrote.
 * @param from - From the read index; why: where the unread text starts.
 * @param to - From the write index; why: where it ends.
 */
function ringLines(bytes: Buffer, from: number, to: number) {
  const mask = bytes.length - 1;
  const start = from & mask;
  const end = to & mask;
  const text =
    start < end
      ? bytes.toString("utf8", start, end)
      : Buffer.concat([bytes.subarray(start), bytes.subarray(0, end)]).toString("utf8");

  const lines = text.split("\n");
  lines.pop();
  return lines;
}

/**
 * Lines go to the drain in turns of 64 (up to 128 records); it waits at 384 of its 512 cap.
 * @param drain - From the command's worker root; why: the queue that takes each line.
 * @param lines - From the ring; why: the lines to take.
 * @param control - From the port; why: a close takes every line without waiting.
 */
async function takeLines(
  drain: TelemetryWorker.Drain,
  lines: string[],
  control: { closing: boolean },
) {
  for (let index = 0; index < lines.length;) {
    const health = drain.health();
    if (!control.closing && health.kind !== "failed" && health.pending >= 384) {
      await sleep(1);
      continue;
    }

    const stop = Math.min(lines.length, index + 64);
    for (; index < stop; index++) drain.take(lines[index]!);
    await new Promise(setImmediate);
  }
}
